<template><section class="music-playlists"><header><h1>{{title||'我的歌单'}}</h1><span>{{reference?sourceName(reference):'网易云音乐 / QQ音乐'}}</span></header><div class="import-tools"><button @click="phoneImport">手机扫码传歌单</button><button @click="manual=!manual">{{manual?'收起输入':'手动输入链接'}}</button><button v-if="reference" @click="reference='';title='';items=[]">‹ 返回歌单</button></div><p v-if="!reference" class="note">手机与设备连接同一 Wi-Fi，扫码打开手机点歌台，进入「歌单」粘贴分享链接。导入后会自动显示在这里。</p><form v-if="manual" @submit.prevent="load(1,true)"><input v-model="input" maxlength="1200" placeholder="粘贴网易云或QQ音乐的歌单分享链接" aria-label="音乐歌单分享链接"/><button :disabled="busy">{{busy?'正在载入…':'载入歌单'}}</button></form><div v-if="!reference" class="playlist-cards"><button v-for="r in recent" :key="r.ref" @click="openRecent(r.ref)"><b>{{r.title}}</b><small>{{sourceName(r.ref)}} · {{r.total}} 首</small></button></div><p v-if="error" class="error" role="alert">{{error}}</p><p v-else class="note">{{warning||(!reference?'公开歌单可直接载入；只取歌曲名单，优先匹配已有MV。':total+'首 · 本地曲库优先，未收录可到B站找MV')}}</p><main v-if="reference||busy||error" ref="list" :aria-busy="busy"><article v-for="(item,i) in items" :key="reference+':'+page+':'+i"><button @click="order(item)"><span class="rank">{{item.rank}}</span><span class="copy"><b>{{item.title}}</b><small>{{item.artists.join(' / ')}}</small></span><span class="action">{{isOrdered(item)?'已点':item.available?'点歌':'B站找歌'}}</span></button></article><p v-if="!items.length&&!busy&&!error" class="empty">载入你喜欢的歌单，在这里唱。</p></main><footer v-if="reference"><button :disabled="busy||page<=1" @click="load(page-1)">上一页</button><span>第 {{page}} 页</span><button :disabled="busy||!hasMore" @click="load(page+1)">下一页</button></footer></section></template>
<script setup>
import {onMounted,onUnmounted,ref} from 'vue'
import {useRouter} from 'vue-router'
import {musicRequest} from '../api/music'
import api from '../api/client'
import {usePlayerStore} from '../stores/player'
import {useToast} from '../composables/useToast'
const manual=ref(false),input=ref(''),title=ref(''),reference=ref(''),recent=ref([]),items=ref([]),page=ref(1),total=ref(0),hasMore=ref(false),busy=ref(false),error=ref(''),warning=ref(''),list=ref(null),player=usePlayerStore(),router=useRouter(),{toast}=useToast()
let polling=false,timer
function sourceName(value){return value.startsWith('netease:')?'网易云音乐':'QQ音乐'}
function phoneImport(){window.dispatchEvent(new Event('woniu-open-phone'))}
async function recentList(){if(polling||document.hidden||reference.value)return;polling=true;try{recent.value=await musicRequest('playlists/recent')}catch{}finally{polling=false}}
async function load(target,refresh=false,refValue=''){if(busy.value)return;const link=refValue||(target===1?input.value:reference.value);if(!link.trim())return;busy.value=true;error.value='';try{const result=await musicRequest('playlist?'+new URLSearchParams({link,page:target,refresh:refresh?'1':'0'}));items.value=result.items;title.value=result.title;reference.value=result.ref;page.value=result.page;total.value=result.total;hasMore.value=result.hasMore;warning.value=result.warning||'';if(list.value)list.value.scrollTop=0;recentList()}catch(e){error.value=e.message}finally{busy.value=false}}
function openRecent(value){if(!value)return;const [source,id]=value.split(':');input.value=source==='netease'?'https://music.163.com/playlist?id='+id:'https://y.qq.com/n/ryqq/playlist/'+id;load(1,false,value)}
function isOrdered(item){return item.song&&player.orderedSongIds.has(String(item.song.id))}
async function order(item){if(isOrdered(item)){toast('这首歌已点');return}if(!item.available||!item.song){if(item.warning)toast(item.warning);router.push({name:'bilibili',query:{keyword:[item.title,...item.artists,'MV'].join(' '),matchTitle:item.title,matchArtists:JSON.stringify(item.artists)}});return}try{player.applySnapshot(await api.control('order',{song_id:item.song.id}));toast('已加入队列')}catch(e){toast(e.message)}}
onMounted(()=>{recentList();timer=setInterval(recentList,5000)})
onUnmounted(()=>clearInterval(timer))
</script>
<style scoped>
.import-tools{display:flex;gap:10px;flex-wrap:wrap}.playlist-cards{flex:1;min-height:0;align-content:start;display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:12px;overflow:auto}.playlist-cards button{text-align:left;min-height:90px;padding:16px}.playlist-cards b,.playlist-cards small{display:block;overflow-wrap:anywhere}.playlist-cards b{font-size:18px;color:var(--text)}.playlist-cards small{margin-top:10px;color:var(--dim)}

.music-playlists{height:100%;min-height:0;display:flex;flex-direction:column;gap:8px}.music-playlists header{display:flex;align-items:center;gap:20px;min-height:32px}.music-playlists h1{font-size:20px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;max-width:55vw}.music-playlists header span,.note{font-size:11px;color:var(--dim2)}.music-playlists form{display:flex;gap:8px}.music-playlists input{flex:1;min-width:0;background:var(--panel);border:1px solid var(--line);border-radius:9px;padding:10px 12px;color:var(--text);font-size:14px}.music-playlists button,.music-playlists select{border:1px solid var(--line);border-radius:9px;background:var(--panel2);color:var(--gold);padding:8px 14px;font-size:12px}.music-playlists select{max-width:180px}.note,.error{margin:0}.error{color:#c97942;font-size:13px}.music-playlists main{flex:1;min-height:0;overflow:auto;display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:9px;align-content:start;padding:3px}.music-playlists article{min-width:0}.music-playlists article button{display:flex;width:100%;align-items:center;gap:12px;min-height:82px;text-align:left;padding:10px 14px;background:var(--tile);color:var(--text);border-radius:12px}.rank{font-size:20px;color:var(--gold)}.copy{min-width:0;flex:1}.copy b,.copy small{display:block;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.copy b{font-size:17px;font-weight:600}.copy small{font-size:12px;color:var(--dim);margin-top:6px}.action{font-size:11px;color:var(--gold);flex:none}.empty{grid-column:1/-1;color:var(--dim2);text-align:center;padding:30px}.music-playlists footer{display:flex;justify-content:center;align-items:center;gap:16px;font-size:12px}
</style>
